package dev.queiroz.relay.status.web;
import dev.queiroz.relay.api.pagination.*; import dev.queiroz.relay.ingestion.application.*; import dev.queiroz.relay.ingestion.domain.TenantId; import dev.queiroz.relay.status.application.StatusStore;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest; import org.springframework.test.context.bean.override.mockito.MockitoBean; import org.springframework.test.web.servlet.MockMvc;
import java.time.Instant; import java.util.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.BDDMockito.given; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(StatusController.class) class StatusControllerTest {
 @Autowired MockMvc mvc; @MockitoBean StatusStore store; @MockitoBean ApiKeyService keys; @MockitoBean TenantRateLimitService limits; @MockitoBean CursorCodec cursors; static final TenantId TENANT=new TenantId("tenant-a"); static final String KEY="key";
 @BeforeEach void auth(){given(keys.authenticate(KEY)).willReturn(Optional.of(TENANT));given(limits.allowRequest(TENANT)).willReturn(true);}
 @Test void returnsOnlySafeEventAndDeliveryFields()throws Exception{UUID event=UUID.randomUUID(),delivery=UUID.randomUUID();given(store.event(TENANT,event)).willReturn(Optional.of(new StatusStore.EventSummary(event,"payment.created","ACCEPTED",Instant.EPOCH)));given(store.delivery(TENANT,delivery)).willReturn(Optional.of(new StatusStore.DeliverySummary(delivery,event,UUID.randomUUID(),"PENDING",0,Instant.EPOCH,Instant.EPOCH,Instant.EPOCH)));
  mvc.perform(get("/v1/events/{id}",event).header("X-Relay-Api-Key",KEY)).andExpect(status().isOk()).andExpect(jsonPath("$.payload").doesNotExist()).andExpect(jsonPath("$.status").value("ACCEPTED"));
  mvc.perform(get("/v1/deliveries/{id}",delivery).header("X-Relay-Api-Key",KEY)).andExpect(status().isOk()).andExpect(jsonPath("$.destinationUrl").doesNotExist()).andExpect(jsonPath("$.leaseToken").doesNotExist());}
 @Test void rejectsBadQueriesAndHidesForeignResources()throws Exception{UUID id=UUID.randomUUID();given(store.event(TENANT,id)).willReturn(Optional.empty());mvc.perform(get("/v1/events/{id}",id).header("X-Relay-Api-Key",KEY)).andExpect(status().isNotFound());mvc.perform(get("/v1/events?limit=101").header("X-Relay-Api-Key",KEY)).andExpect(status().isBadRequest());given(cursors.decode("bad","v1/events",TENANT)).willThrow(new InvalidCursorException());mvc.perform(get("/v1/events?cursor=bad").header("X-Relay-Api-Key",KEY)).andExpect(status().isBadRequest());}
 @Test void listsAndSanitizesAttempts()throws Exception{UUID delivery=UUID.randomUUID(),attempt=UUID.randomUUID();given(store.delivery(TENANT,delivery)).willReturn(Optional.of(new StatusStore.DeliverySummary(delivery,UUID.randomUUID(),UUID.randomUUID(),"SUCCEEDED",1,null,Instant.EPOCH,Instant.EPOCH)));given(store.attempts(eq(TENANT),eq(delivery),isNull(),eq(21))).willReturn(List.of(new StatusStore.AttemptSummary(attempt,delivery,1,Instant.EPOCH,Instant.EPOCH,"SUCCEEDED",200,null)));mvc.perform(get("/v1/deliveries/{id}/attempts",delivery).header("X-Relay-Api-Key",KEY)).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].sanitizedErrorCode").isEmpty()).andExpect(jsonPath("$.data[0].responseBody").doesNotExist());}
}
